  1	import java.util.ArrayList;
  2	import java.util.Collections;
  3	import java.util.List;
  4	
  5	public final class FloydWarshall {
  6	
  7	    public static final int INF = 100_000_000;
  8	
  9	    private FloydWarshall() {
 10	        // Utility class.
 11	    }
 12	
 13	    public static Result computeShortestPaths(int[][] graph) {
 14	        validateSquareMatrix(graph);
 15	
 16	        int[][] distances = copyMatrix(graph);
 17	        int[][] nextHop = new int[graph.length][graph.length];
 18	        initializeNextHop(graph, nextHop);
 19	
 20	        int vertices = distances.length;
 21	        for (int k = 0; k < vertices; k++) {
 22	            for (int i = 0; i < vertices; i++) {
 23	                if (distances[i][k] == INF) {
 24	                    continue;
 25	                }
 26	
 27	                for (int j = 0; j < vertices; j++) {
 28	                    if (distances[k][j] == INF) {
 29	                        continue;
 30	                    }
 31	
 32	                    int throughK = distances[i][k] + distances[k][j];
 33	                    if (throughK < distances[i][j]) {
 34	                        distances[i][j] = throughK;
 35	                        nextHop[i][j] = nextHop[i][k];
 36	                    }
 37	                }
 38	            }
 39	        }
 40	
 41	        return new Result(distances, nextHop);
 42	    }
 43	
 44	    private static void initializeNextHop(int[][] graph, int[][] nextHop) {
 45	        for (int i = 0; i < graph.length; i++) {
 46	            for (int j = 0; j < graph.length; j++) {
 47	                nextHop[i][j] = graph[i][j] == INF ? -1 : j;
 48	            }
 49	        }
 50	    }
 51	
 52	    private static void validateSquareMatrix(int[][] matrix) {
 53	        if (matrix == null) {
 54	            throw new IllegalArgumentException("Matrix must not be null.");
 55	        }
 56	
 57	        for (int i = 0; i < matrix.length; i++) {
 58	            if (matrix[i] == null) {
 59	                throw new IllegalArgumentException("Matrix row " + i + " must not be null.");
 60	            }
 61	
 62	            if (matrix[i].length != matrix.length) {
 63	                throw new IllegalArgumentException("Matrix must be square.");
 64	            }
 65	        }
 66	    }
 67	
 68	    private static void validateVertex(int vertex, int size) {
 69	        if (vertex < 0 || vertex >= size) {
 70	            throw new IllegalArgumentException("Vertex index out of bounds: " + vertex);
 71	        }
 72	    }
 73	
 74	    private static int[][] copyMatrix(int[][] source) {
 75	        int[][] copy = new int[source.length][];
 76	        for (int i = 0; i < source.length; i++) {
 77	            copy[i] = source[i].clone();
 78	        }
 79	        return copy;
 80	    }
 81	
 82	    public static final class Result {
 83	        private final int[][] distances;
 84	        private final int[][] nextHop;
 85	
 86	        private Result(int[][] distances, int[][] nextHop) {
 87	            this.distances = copyMatrix(distances);
 88	            this.nextHop = copyMatrix(nextHop);
 89	        }
 90	
 91	        public int vertexCount() {
 92	            return distances.length;
 93	        }
 94	
 95	        public int[][] distances() {
 96	            return copyMatrix(distances);
 97	        }
 98	
 99	        public int distance(int source, int target) {
100	            validateVertex(source, distances.length);
101	            validateVertex(target, distances.length);
102	            return distances[source][target];
103	        }
104	
105	        public List<Integer> path(int source, int target) {
106	            validateVertex(source, distances.length);
107	            validateVertex(target, distances.length);
108	
109	            if (nextHop[source][target] == -1) {
110	                return Collections.emptyList();
111	            }
112	
113	            List<Integer> path = new ArrayList<>();
114	            int current = source;
115	            path.add(current);
116	
117	            while (current != target) {
118	                current = nextHop[current][target];
119	                if (current == -1) {
120	                    return Collections.emptyList();
121	                }
122	                path.add(current);
123	            }
124	
125	            return Collections.unmodifiableList(path);
126	        }
127	
128	        public boolean isReachable(int source, int target) {
129	            validateVertex(source, distances.length);
130	            validateVertex(target, distances.length);
131	            return nextHop[source][target] != -1;
132	        }
133	
134	        public boolean hasNegativeCycle() {
135	            for (int i = 0; i < distances.length; i++) {
136	                if (distances[i][i] < 0) {
137	                    return true;
138	                }
139	            }
140	            return false;
141	        }
142	    }
143	}

